import { NextRequest, NextResponse } from 'next/server';
import { supabase } from '@/lib/supabase';
import prisma from '@/lib/prisma';
import { sign } from 'jsonwebtoken';

const JWT_SECRET = process.env.JWT_SECRET || 'shramsetu-secret-key-change-this-in-production-abc123xyz';

export async function POST(request: NextRequest) {
    try {
        const { supabaseToken, phone } = await request.json();

        if (!supabaseToken || !phone) {
            return NextResponse.json({ error: 'Missing token or phone' }, { status: 400 });
        }

        // 1. Verify token with Supabase
        const { data: { user: supabaseUser }, error } = await supabase.auth.getUser(supabaseToken);

        if (error || !supabaseUser) {
            console.error('Supabase auth error:', error);
            return NextResponse.json({ error: 'Invalid Supabase token' }, { status: 401 });
        }

        // Optional: Verify phone matches (Supabase user.phone might be formatted differently, e.g. +91...)
        // if (supabaseUser.phone !== phone) ...

        // 2. Find or Create User in Our DB (Prisma)
        let user = await prisma.user.findUnique({
            where: { phone },
            include: { workerProfile: true, employerProfile: true }
        });

        let isNewUser = false;

        if (!user) {
            isNewUser = true;
            user = await prisma.user.create({
                data: {
                    phone,
                    name: 'New User', // Placeholder
                    city: 'Delhi',
                    language: 'en',
                },
                include: { workerProfile: true, employerProfile: true }
            });
        }

        // 3. Issue Custom JWT (for existing APIs compatibility)
        const token = sign(
            { userId: user.id, phone: user.phone },
            JWT_SECRET,
            { expiresIn: '30d' }
        );

        return NextResponse.json({
            success: true,
            token,
            user: {
                id: user.id,
                phone: user.phone,
                name: user.name,
                language: user.language,
                city: user.city,
                hasWorkerProfile: !!user.workerProfile,
                hasEmployerProfile: !!user.employerProfile,
                workerProfile: user.workerProfile ? {
                    ...user.workerProfile,
                    skills: typeof user.workerProfile.skills === 'string'
                        ? JSON.parse(user.workerProfile.skills || '[]')
                        : user.workerProfile.skills,
                    portfolioImages: typeof user.workerProfile.portfolioImages === 'string'
                        ? JSON.parse(user.workerProfile.portfolioImages || '[]')
                        : user.workerProfile.portfolioImages,
                    certifications: (user.workerProfile.certifications && typeof user.workerProfile.certifications === 'string')
                        ? JSON.parse(user.workerProfile.certifications)
                        : []
                } : null,
                employerProfile: user.employerProfile ? {
                    ...user.employerProfile,
                    categories: typeof user.employerProfile.categories === 'string'
                        ? JSON.parse(user.employerProfile.categories || '[]')
                        : user.employerProfile.categories
                } : null,
                isNewUser,
            }
        });

    } catch (error) {
        console.error('Supabase Login Error:', error);
        return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
    }
}
